def _clear_social_vk_rate_backoff():
    db = SessionLocal()
    try:
        row = db.query(Storage).filter(
            Storage.account_id == _SOCIAL_VK_BACKOFF_ACCOUNT,
            Storage.key == _SOCIAL_VK_RATE_BACKOFF_KEY,
